import {combatRates} from './combat.mjs';
import {META_KEY,createMeta,normalizeMeta,prepareRun,applyStartingCards,selectCard,drawCard,finishRun} from './meta.mjs';
import {lobbyPanel,scorePanel} from './meta-ui.mjs';
import {combatAttribute,permanentRates} from './attributes.mjs';
import {powersPanel,powerDialog} from './powers-ui.mjs';
import {compactHud,turnBattleView,skillDialog,characterDialog,opponentDialog} from './turn-ui.mjs';
import {playTurn,settleEnemy} from './combat.mjs';
import {resourceBar,buildTabs,skillsPanel,equipmentPanel} from './management-ui.mjs';
import {manageBuild} from './management.mjs';
import {ACTIVE_LIMIT,learnedPassives} from './passives.mjs';
import {campaignFor} from './campaign.mjs';
import {initial,scene,choose,pathName,art,migrate,relationshipEvents} from './engine.mjs';
import {journeyPanel} from './journey-ui.mjs';
import {marketPanel} from './market-ui.mjs';
import {battleStage,effectsDuration} from './battle-stage.mjs';
import {zoneFor,xpNeeded} from './journey.mjs';
import {abilities,combatStats,effectiveStats,weaponProfiles,elementDescriptions,tickBattle,fastForward,maxHp,maxEnergy} from './combat.mjs';
import {pathInfo} from './paths.mjs';
import {statGuide,skillInfo,growthPanel,basicInfo} from './insight-ui.mjs';
import {abilityCatalog} from './combat.mjs';
import {activeStatuses} from './statuses.mjs';
const $=id=>document.getElementById(id),key='hannui-first-breath-v1';
let collection=createMeta(),pendingName='',cardCategory='character';try{collection=normalizeMeta(JSON.parse(localStorage.getItem(META_KEY)||'null'));}catch{}
function persistCollection(){try{localStorage.setItem(META_KEY,JSON.stringify(collection));return true;}catch{return false;}}
let state=null,saved=null,storageOk=true,saveWarning='',timer=null,paused=false,speed=1,catalogFilter='consumable',panel='story',tabWasPlaying=false;
const escape=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
try{const raw=localStorage.getItem(key);if(raw){try{saved=migrate(JSON.parse(raw));}catch{saveWarning='기존 저장을 읽지 못했습니다. 새 여정을 시작할 수 있습니다.';}}}catch{storageOk=false;}
function persist(){try{localStorage.setItem(key,JSON.stringify(state));saved=structuredClone(state);storageOk=true;}catch{storageOk=false;}}
function stopTimer(){if(timer!==null)clearTimeout(timer);timer=null;}
function landing(){panel='story';stopTimer();state=null;$('app').innerHTML=`<section class="hero flash"><div><p class="eyebrow">HAN NUI · AN ILLUSTRATED TEXT RPG</p><h1>당신의 이름으로,<br><em>첫 숨을 열다.</em></h1><p class="intro">무엇을 쥘 것인가. 어떤 힘을 따를 것인가.<br>당신의 선택이 길을 만들고,<br>쌓아 온 힘이 전장에서 이야기를 이어갑니다.</p><div class="hero-tags"><span>장면 삽화</span><span>선택과 성장</span><span>턴제 전투</span></div><form id="start" class="name-form"><label for="name">이야기에 남길 이름</label><input id="name" name="name" maxlength="16" placeholder="제자의 이름을 입력하세요" autocomplete="off" required><p id="name-error" class="error" aria-live="polite">${escape(saveWarning)}</p><button class="primary wide">새로운 이야기 시작하기 ↗</button><div class="sub-action"><button type="button" class="quiet" id="open-collection">카드 수집 · 보석 ${collection.gems}</button></div><div class="sub-action">${saved?`<button type="button" class="quiet" id="resume">${escape(saved.name)}의 이야기 이어가기 →</button>`:'<span class="muted">서장과 두 개의 챕터 · 탐험과 성장</span>'}</div></form></div><figure class="hero-art"><img src="assets/courtyard.png" alt="소나무와 운무가 감싼 산중 수련처 여울원, 새벽빛 아래 제자들이 수련한다." fetchpriority="high"><figcaption>여울원 · 모든 길이 시작되는 곳</figcaption></figure></section>`;
 $('start').onsubmit=e=>{e.preventDefault();const name=$('name').value.trim();if(!name||name.length>16){$('name-error').textContent='1~16자로 이름을 입력해 주세요.';return;}if(saved){$('new-name').value=name;$('restart').showModal();}else start(name);};$('open-collection').onclick=()=>openLobby($('name').value.trim()||saved?.name||'서린');if(saved)$('resume').onclick=()=>{state=migrate(saved);paused=state.scene==='battle'&&!state.battle.outcome;persist();render();};}
function confirmChapterRetry(){stopTimer();state=choose(state,'retry-chapter');paused=false;persist();$('chapter-retry').close();render();}
function start(name){openLobby(name);}
function canSettle(s){return !!s.runSetup&&!!s.journey?.route?.ended&&!s.journey.points&&s.scene!=='ability-evolution'&&(s.journey.route.ended==='defeat'||s.journey.chapter===2);}
function openLobby(name){state=null;panel='lobby';pendingName=name;stopTimer();$('app').innerHTML=lobbyPanel(collection,pendingName,cardCategory);$('lobby-name').oninput=e=>{pendingName=e.target.value;};$('lobby-back').onclick=landing;document.querySelectorAll('[data-card-category]').forEach(button=>button.onclick=()=>{cardCategory=button.dataset.cardCategory;openLobby(pendingName);});document.querySelectorAll('[data-card]').forEach(button=>button.onclick=()=>{try{collection=selectCard(collection,button.dataset.card);persistCollection();openLobby(pendingName);}catch(e){$('lobby-note').textContent=e.message;}});$('draw-card').onclick=()=>{try{collection=drawCard(collection);persistCollection();openLobby(pendingName);document.querySelector('.card-draw').open=true;}catch(e){$('lobby-note').textContent=e.message;}};$('launch-run').onclick=()=>{const name=$('lobby-name').value.trim();if(!name||name.length>16){$('lobby-note').textContent='이름을 1~16자로 입력하세요.';return;}const run=prepareRun(collection,name);collection=run.meta;persistCollection();state=applyStartingCards(initial(name),run.setup);state.hp=maxHp(state);state.energy=maxEnergy(state);panel='story';paused=false;persist();render();};window.scrollTo({top:0,behavior:'instant'});}

function bar(label,value,max,theme=''){return `<div class="stat ${theme}"><div class="stat-label"><span>${label}</span><span>${value} / ${max}</span></div><div class="bar"><i style="width:${Math.max(0,Math.min(100,value/max*100))}%"></i></div></div>`;}
function illustration(){if(state.journey){const z=['combat','battle'].includes(state.scene)?zoneFor(state.journey.active):state.scene==='reward'?zoneFor(state.journey.reward.zone):null;const file=z?.image||(state.scene==='chapter-event'?state.journey.route.current?.image:null)||(campaignFor(state).id===2?'cheongun':['growth'].includes(state.scene)?'spring':'courtyard');return `<figure class="scene-art ${state.scene==='battle'?'battle-art':''}"><img src="assets/${file}.png" alt="산중의 수련처와 산 아래 길을 그린 삽화" width="1536" height="1024"><figcaption><span>${z?.name||campaignFor(state).title}</span><span>CHAPTER 0${campaignFor(state).id}</span></figcaption></figure>`;}const spring=['spring','commit','element'].includes(state.scene),bridge=['mission','combat','battle','bridge'].includes(state.scene),file=bridge?'bridge':spring?'spring':'courtyard';const caption=bridge?'산 아래 계곡 · 끊어지는 다리':spring?'여울원의 샘 · 숨이 깨어나는 자리':'여울원 · 수련의 뜰';const alt=bridge?'안개 낀 계곡을 건너는 낡은 밧줄 다리, 건너편에 약탈자가 서 있다.':spring?'맑은 샘물 위로 옅은 옥빛 숨이 흐르고 잎 하나가 떠 있다.':'기와 지붕의 산중 수련처와 마당, 겹겹의 산 사이로 새벽빛이 든다.';return `<figure class="scene-art ${state.scene==='battle'?'battle-art':''}"><img src="assets/${file}.png" alt="${alt}" decoding="async" width="1536" height="1024"><figcaption><span>${caption}</span><span>${state.scene==='battle'?'ENCOUNTER 01':'HAN NUI'}</span></figcaption></figure>`;}
function statSnapshot(){const rates=combatRates(state),values=[['근력',combatAttribute(state,'skill')],['민첩',combatAttribute(state,'insight')],['지능',combatAttribute(state,'control')],['매력',combatAttribute(state,'charisma')],['치명타',Math.round(rates.critical*100)+'%'],['회피',Math.round(rates.evasion*100)+'%']];return '<section class="player-stats" aria-label="현재 내 능력치"><dl>'+values.map(([name,value])=>'<div><dt>'+name+'</dt><dd>'+value+'</dd></div>').join('')+'</dl></section>';}

function statusBadges(side){const list=activeStatuses(state,side);return `<div class="status-badges" aria-label="${side==='player'?'내':'상대'} 상태이상">${list.length?list.map(r=>`<details class="status-info status-${r.id}"><summary><span>${r.name}${r.stacks>1?' '+r.stacks+'중첩':''} · ${r.turns}회</span></summary><p>${r.description}</p></details>`).join(''):'<span class="status-clear">상태이상 없음</span>'}</div>`;}
function pathGuide(preview=false){const info=pathInfo(preview?{...state,path:state.trial}:state);return `<details class="path-guide" ${preview?'open':''}><summary>${info.name} · ${info.cycle}</summary><p>${info.summary}</p></details>`;}
function pathCombat(){const p=state.battle.pathState||{},info=pathInfo(state);return `<section class="path-combat ${state.path}" aria-label="숨의 길 전투 상태"><div><strong>${info.name}</strong></div>${state.path==='inner'?`<div class="vigor-meter" aria-label="축기 ${p.vigor||0} / 3">${[1,2,3].map(n=>`<i class="${n<=(p.vigor||0)?'filled':''}"></i>`).join('')}<span>축기 ${p.vigor||0}/3</span></div>`:`<div class="spell-state"><span>공명 ${state.battle.techniqueState?.resonance||0}/3</span><span class="${p.casting?'preparing':''}">${p.casting?'준비 중 · '+escape(p.casting.name):'주문 연결 대기'}</span>${p.field?`<span>유지 영역 · ${p.field.turns}회${p.field.ward?' · 보호막 보충':''}</span>`:''}${p.renewal?`<span>생기 순환 · ${p.renewal}회</span>`:''}${state.battle.enemy.disrupted?`<span>적 교란 · ${state.battle.enemy.disrupted}회</span>`:''}</div>`}</section>`;}
function sidebar(){const j=state.journey;return `<aside class="sidebar"><div class="profile"><h2>${escape(state.name)}</h2><span class="rank">${j?'등급 '+j.level:'제자'}</span></div><p class="build-line">${[state.weapon,state.element,state.path?pathName(state):null].filter(Boolean).join(' · ')}</p><div class="vitals">${bar('체력',state.hp,maxHp(state),'health')}${state.path?bar(pathInfo(state).resource,state.energy,maxEnergy(state)):''}</div>${statSnapshot()}${j?`<div class="sidebar-xp">${bar('경험',j.xp,xpNeeded(j))}</div>`:''}<div class="build-counts"><span>기술 ${equipped().length}/4</span><span>능력 ${(state.passiveLoadout||[]).length}/3</span></div></aside>`;}
function visibleChoices(data){data={...data,choices:data.choices.filter(c=>!['open-bag','open-growth'].includes(c.id))};const routeFiltered=['hub','map'].includes(state.scene)?{...data,choices:data.choices.filter(c=>!c.id.startsWith('node-'))}:data;const prefix={map:['explore-'],shop:['buy-item-'],bag:['equip-item-','use-item-'],school:['learn-'],synthesis:['combine-']}[state.scene]||[];return {...data,choices:routeFiltered.choices.filter(c=>!prefix.some(p=>c.id.startsWith(p)))};}
function choiceList(data){if(state.scene==='growth')return growthPanel(state,data)+statGuide(state);const extra=new Set(['open-bag','open-growth']),secondary=data.choices.filter(c=>extra.has(c.id)||(state.scene==='growth'&&/^(study-|hone-)/.test(c.id))),primary=data.choices.filter(c=>!secondary.includes(c));const list=(choices)=>choices.map((c,i)=>`<button class="choice" data-choice="${c.id}" ${c.disabled?'disabled':''}><span class="num">${String(i+1).padStart(2,'0')}</span><span><strong>${escape(c.title)}</strong>${c.hint&&['ability-evolution','first-lesson','growth','combat','shop','school','synthesis','bag','forge'].includes(state.scene)?`<small>${escape(c.hint)}</small>`:''}${state.scene==='first-lesson'?skillInfo(state,abilityCatalog(state).find(a=>a.id===c.id.replace('pick-',''))||{}):''}</span><span class="arrow" aria-hidden="true">→</span></button>`).join('');return `${primary.length?`<div class="choice-caption">${state.scene==='growth'&&state.journey.points>0?'성장점이 남아 있습니다 · 모두 배분하세요':state.scene==='first-lesson'?'이번에 배울 기술 · 하나를 선택하세요':'다음 행동을 선택하세요'}</div><div class="choices">${list(primary)}</div>`:''}${secondary.length?`<details class="management"><summary>${state.scene==='growth'?'새 기술 습득과 강화':'소지품과 성장 관리'}${state.journey?.points?' · 성장점 '+state.journey.points:''}</summary><div class="choices">${list(secondary)}</div></details>`:''}`;}
function equipped(){return state.loadout??abilities(state).slice(0,ACTIVE_LIMIT).map(a=>a.id);}
function preparation(){const active=abilities(state).filter(a=>equipped().includes(a.id));return `<section class="preparation compact-preparation"><div class="section-title"><span>기술 ${active.length}/4 · 능력 ${(state.passiveLoadout||[]).length}/3</span><div><button class="quiet" data-tab="skills">기술 편집</button><button class="quiet" data-tab="equipment">장비 편집</button></div></div><div class="combat-plan">${active.map(a=>`<span class="equipped-skill">${a.name}</span>`).join('')||'<span>기본 공격 · 방어</span>'}</div></section>`;}
function battleView(){return turnBattleView(state,statSnapshot,pathCombat);}
function relationPanel(){const events=relationshipEvents(state);return `<details class="relations"><summary>인연의 기록 <span>이솔 · ${events.length}개의 기억</span></summary><p>수련처에서 만난 동료. 함께 겪은 사건이 두 사람 사이에 남습니다.</p>${events.length?`<ul>${events.map(e=>`<li>${escape(e)}</li>`).join('')}</ul>`:'<p class="muted">아직 함께한 사건이 기록되지 않았습니다.</p>'}</details>`;}
function battleHistory(){return state.battle?.outcome&&state.scene!=='battle'?`<details class="journal"><summary>최근 전투 기록 · ${{victory:'승리',defeat:'전투 불능',retreat:'후퇴'}[state.battle.outcome]}</summary><ol>${state.battle.log.map(e=>`<li>${escape(e.text)}</li>`).join('')}</ol></details>`:'';}
function recordView(){return `<h1 id="scene-title" tabindex="-1">기록</h1>${relationPanel()}${battleHistory()}<details class="journal" open><summary>여정의 기록 · ${state.journal.length}개</summary><ol>${state.journal.map(j=>`<li><span>${escape(j.scene)}</span> — ${escape(j.choice)}</li>`).join('')}</ol></details>`;}
function render(focus=true){if(state?.scene==='battle'&&state.battle.actor==='enemy'&&!state.battle.outcome){state=settleEnemy(state);persist();}const expanded=focus?[]:[...document.querySelectorAll('details[open]')].map(d=>d.className).filter(Boolean);stopTimer();const data=scene(state),isBattle=state.scene==='battle';
 const story=`<div class="chapter-nav"><span>${state.journey?'챕터 '+campaignFor(state).id+' · '+campaignFor(state).title:'서장 · 첫 번째 숨 / '+['','이름과 길','수련의 날들','첫 번째 시련','당신의 발자국'][data.chapter]}</span><span class="dots" aria-label="${state.journey?'중간 선택 '+state.journey.route.used+' / '+state.journey.route.total:'4장 중 '+data.chapter+'장'}">${(state.journey?Array.from({length:state.journey.route.total+1},(_,i)=>i+1):[1,2,3,4]).map(n=>`<i class="${state.journey?(n<=state.journey.route.used||(n===state.journey.route.total+1&&state.journey.route.ended)?'active':''):(n<=data.chapter?'active':'')}"></i>`).join('')}</span></div>${state.last?`<div class="notice" role="status">${escape(state.last)}</div>`:''}<p class="eyebrow">${isBattle?'TURN BASED COMBAT':`${state.journey?'CHAPTER 0'+campaignFor(state).id:`CHAPTER 0${data.chapter}`}`}</p><h1 tabindex="-1" id="scene-title">${data.title}</h1>${isBattle?'':illustration()}<div class="prose">${data.text.slice(0,state.journey?1:data.text.length).map(t=>`<p>${escape(t)}</p>`).join('')}${state.journey&&data.text.length>1?`<details class="story-detail"><summary>이야기 더 읽기</summary>${data.text.slice(1).map(t=>`<p>${escape(t)}</p>`).join('')}</details>`:''}</div>${state.scene==='commit'?pathGuide(true):''}${data.quote?`<blockquote class="quote">${data.quote}</blockquote>`:''}${journeyPanel(state)}${marketPanel(state)}${state.scene==='combat'?preparation():''}${isBattle?battleView():''}${state.scene==='ending'?ending():data.choices.length?choiceList(visibleChoices(data)):''}${canSettle(state)?scorePanel(state,collection.settledRuns.includes(state.runSetup.id)):''}<div class="story-bottom"><span class="saved">${storageOk?'이 브라우저에 자동 저장됨':'자동 저장 불가 · 현재 창에서 계속 플레이할 수 있습니다'}</span><button class="quiet" id="home">처음 화면으로</button></div>`;
 const content=panel==='skills'?skillsPanel(state):panel==='powers'?powersPanel(state):panel==='equipment'?equipmentPanel(state):panel==='record'?recordView():story;
 $('app').innerHTML=`<div class="game-shell"><div class="game-toolbar">${compactHud(state)}${resourceBar(state)}</div>${buildTabs(panel)}<div class="game-layout ${isBattle&&panel==='story'?'in-battle':''}"><article id="game-panel" role="tabpanel" aria-labelledby="tab-${panel}" data-scene="${state.scene}" class="story ${focus?'flash':''}">${content}</article></div></div>`;
 if(!focus)document.querySelectorAll('details').forEach(d=>{if(expanded.includes(d.className))d.open=true;});
 document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{const id=b.dataset.choice,inline=/^(buy-item-|equip-item-|use-item-|learn-|combine-)/.test(id),position=window.scrollY;if(id==='retry-chapter'){$('chapter-retry').showModal();return;}state=choose(state,id);panel='story';tabWasPlaying=false;paused=false;persist();render(!inline);if(inline)window.scrollTo({top:position,behavior:'instant'});});
 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>switchPanel(b.dataset.tab));
 document.querySelectorAll('[role="tab"]').forEach(b=>b.onkeydown=e=>{const ids=['story','skills','powers','equipment','record'],i=ids.indexOf(panel);if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?ids[0]:e.key==='End'?ids[4]:ids[(i+(e.key==='ArrowRight'?1:4))%5];switchPanel(next);document.getElementById('tab-'+next)?.focus();}});
 document.querySelectorAll('[data-manage]').forEach(b=>b.onclick=()=>{const position=window.scrollY;try{state=manageBuild(state,b.dataset.manage,b.dataset.id);persist();render(false);document.querySelector(`[data-manage="${b.dataset.manage}"][data-id="${b.dataset.id}"]`)?.focus({preventScroll:true});window.scrollTo({top:position,behavior:'instant'});}catch(e){$('build-note').textContent=e.message;}});

 document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{catalogFilter=b.dataset.filter;applyCatalogFilter();});applyCatalogFilter();
 if($('settle-run'))$('settle-run').onclick=()=>{collection=finishRun(collection,state);state.runSetup.settled=true;persistCollection();persist();openLobby(state.name);};if($('home'))$('home').onclick=landing;if($('download'))$('download').onclick=download;if($('replay'))$('replay').onclick=()=>{$('new-name').value=state.name;$('restart').showModal();};
 document.querySelectorAll('[data-battle-action]').forEach(button=>button.onclick=()=>{try{state=playTurn(state,button.dataset.battleAction);persist();render(false);}catch(e){showDetail('<p>'+escape(e.message)+'</p>');}});
 document.querySelectorAll('[data-inspect]').forEach(button=>button.onclick=()=>showDetail(skillDialog(state,button.dataset.inspect)));
 document.querySelectorAll('[data-opponent]').forEach(button=>button.onclick=()=>showDetail(opponentDialog(state)));
 document.querySelectorAll('[data-power]').forEach(button=>button.onclick=()=>showDetail(powerDialog(state,button.dataset.power)));
 document.querySelectorAll('[data-character]').forEach(button=>button.onclick=()=>showDetail(characterDialog(state)));

 if(focus){$('scene-title').focus({preventScroll:true});if(isBattle&&panel==='story')document.querySelector('.turn-battle')?.scrollIntoView({block:'start',behavior:'instant'});else window.scrollTo({top:0,behavior:'instant'});}}
function switchPanel(next){if(!['story','skills','powers','equipment','record'].includes(next))return;
 if(panel==='story'&&next!=='story'){tabWasPlaying=state?.scene==='battle'&&!paused&&!state.battle.outcome;if(tabWasPlaying)paused=true;}
 panel=next;if(next==='story'&&tabWasPlaying){paused=false;tabWasPlaying=false;}render(false);
 window.scrollTo({top:document.querySelector('.game-shell')?.offsetTop||0,behavior:'instant'});
}
function applyCatalogFilter(){document.querySelectorAll('[data-item-type]').forEach(card=>{card.hidden=catalogFilter!=='all'&&card.dataset.itemType!==catalogFilter;});document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===catalogFilter));}
function ending(){return `<div class="result-grid"><div><small>당신이 연 길</small><strong>${pathName(state)}</strong></div><div><small>첫 깨달음</small><strong>${art(state)}</strong></div><div><small>마을에 남긴 기억</small><strong>${{together:'함께 지킨 약속',child:'작은 생명의 은인',herbs:'약을 지킨 제자'}[state.ending]}</strong></div><div><small>이솔과의 인연</small><strong>${state.relations.includes('isol-injured')?'아직 남은 미안함':state.relations.includes('shared-rescue')?'서로 등을 맡긴 사이':'함께 길을 걸은 사이'}</strong></div></div><p class="muted">서장 완료 · 직접 고른 깨달음이 새 궁극기가 됩니다. 이 제자로 다음 의뢰에 나아갈 수 있습니다.</p><button class="primary journey-next" data-choice="next-chapter">첫 번째 의뢰로 나아가기 →</button><div class="sub-action"><button class="primary" id="download">여정 기록 내려받기</button><button class="quiet" id="replay">다른 제자로 시작하기 →</button></div>`;}
function download(){const text=`한뉘 · 첫 번째 숨\n${state.name}의 여정\n${pathName(state)} / ${state.element} / ${state.weapon}\n첫 깨달음: ${art(state)}\n\n`+state.journal.map((j,i)=>`${i+1}. ${j.scene}\n   ${j.choice}`).join('\n')+'\n\n인연의 기록\n'+relationshipEvents(state).join('\n')+(state.battle?'\n\n전투 기록\n'+state.battle.log.map(e=>`[${e.round}] ${e.text}`).join('\n'):'');const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));a.href=url;a.download='한뉘-여정.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function showDetail(html){const dialog=$('detail-dialog');$('detail-content').innerHTML=html;dialog.showModal();}
document.body.insertAdjacentHTML('beforeend','<dialog id="detail-dialog"><div id="detail-content"></div><button class="primary wide" id="close-detail">닫기</button></dialog>');$('close-detail').onclick=()=>$('detail-dialog').close();
document.body.insertAdjacentHTML('beforeend','<dialog id="restart"><h2>새로운 이야기를 시작할까요?</h2><p>현재 브라우저에 저장된 여정이 새 제자의 이야기로 바뀝니다.</p><input type="hidden" id="new-name"><div class="sub-action"><button class="primary" id="confirm-restart">새로 시작하기</button><button class="quiet" id="cancel-restart">돌아가기</button></div></dialog>');
$('confirm-restart').onclick=()=>{const name=$('new-name').value;$('restart').close();start(name);};$('cancel-restart').onclick=()=>$('restart').close();
document.body.insertAdjacentHTML('beforeend','<dialog id="chapter-retry"><h2>이 챕터를 처음부터 다시 도전할까요?</h2><p>이름과 숨의 길은 유지하고, 능력·장비·재화는 이 챕터를 시작했던 상태로 돌아갑니다.</p><p class="chapter-retry-note">이번 도전에서 얻은 보상과 성장은 초기화됩니다. 재도전으로 힘을 누적할 수 없습니다.</p><div class="sub-action"><button class="primary" id="confirm-chapter-retry">시작 상태로 다시 도전</button><button class="quiet" id="cancel-chapter-retry">돌아가기</button></div></dialog>');$('confirm-chapter-retry').onclick=confirmChapterRetry;$('cancel-chapter-retry').onclick=()=>$('chapter-retry').close();
let guideWasPlaying=false;$('help').onclick=()=>{guideWasPlaying=state?.scene==='battle'&&!paused&&!state.battle.outcome;if(guideWasPlaying){paused=true;render(false);}$('guide').showModal();};$('close-guide').onclick=()=>$('guide').close();$('guide').addEventListener('close',()=>{if(guideWasPlaying&&state?.scene==='battle'){paused=false;render(false);}guideWasPlaying=false;});$('brand').onclick=e=>{e.preventDefault();landing();};landing();
